class ValidationErr:
    def __init__(self, variant, value):
        self.variant = variant
        self.value = value

def validatePos(lhs: int) -> int | ValidationErr:
    if lhs <= 0:
        return ValidationErr("TooShort", "Number must be positive")
    result = 0
    i = 0
    while i < lhs:
        result = result + 1
        i = i + 1
    return result

def main():
    test_cases = [
        (5,),
        (1,),
        (0,),
        (-3,),
        (10,),
    ]
    for n in test_cases:
        res = validatePos(*n)
        if isinstance(res, ValidationErr):
            print(f"Err({res.variant}:{res.value})")
        else:
            print(f"Ok({res})")

if __name__ == "__main__":
    main()

