#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    char* TooShort;
    char* TooLong;
    char* InvalidChar;
} ValidationErr;

typedef struct {
    bool is_ok;
    union {
        long long ok;
        ValidationErr err;
    } value;
} Result_i64_ValidationErr;

Result_i64_ValidationErr validatePos(long long n) {
    if (n > 0) {
        Result_i64_ValidationErr result;
        result.is_ok = true;
        result.value.ok = n;
        return result;
    } else {
        Result_i64_ValidationErr result;
        result.is_ok = false;
        result.value.err.TooShort = "Value must be positive";
        result.value.err.TooLong = NULL;
        result.value.err.InvalidChar = NULL;
        return result;
    }
}

int main() {
    long long test_cases[] = {5, 0, -1, 100, -42};
    int num_tests = sizeof(test_cases) / sizeof(test_cases[0]);

    for (int i = 0; i < num_tests; i++) {
        long long lhs = test_cases[i];
        Result_i64_ValidationErr result = validatePos(lhs);

        if (result.is_ok) {
            printf("Test %d: OK - %lld\n", i + 1, result.value.ok);
        } else {
            printf("Test %d: Err - TooShort: %s\n", i + 1, 
                   result.value.err.TooShort ? result.value.err.TooShort : "NULL");
        }
    }

    return 0;
}

