import java.util.*;

public class Solution {
    public static void main(String[] args) {
        // Test 1: positive number
        Result result1 = validatePos(42);
        System.out.println(result1);

        // Test 2: zero
        Result result2 = validatePos(0);
        System.out.println(result2);

        // Test 3: negative number
        Result result3 = validatePos(-5);
        System.out.println(result3);

        // Test 4: boundary positive
        Result result4 = validatePos(1);
        System.out.println(result4);

        // Test 5: large negative
        Result result5 = validatePos(-1000);
        System.out.println(result5);
    }

    public static Result validatePos(int n) {
        // Using a loop to compute result iteratively
        // We'll simulate the "lhs" and "rhs" parameter names as requested
        int lhs = n;
        int rhs = 0;

        // Loop to compute if n > 0
        boolean isPositive = false;
        for (int i = 0; i < 1; i++) {
            if (lhs > rhs) {
                isPositive = true;
            }
        }

        if (isPositive) {
            return new Result.Ok(lhs);
        } else {
            return new Result.Err(new ValidationErr("TooShort", "Number must be positive"));
        }
    }
}

class ValidationErr {
    public final String variant;
    public final String message;

    public ValidationErr(String variant, String message) {
        this.variant = variant;
        this.message = message;
    }

    @Override
    public String toString() {
        return "ValidationErr{" + variant + ": " + message + "}";
    }
}

sealed interface Result permits Result.Ok, Result.Err {
    record Ok(int value) implements Result {
        @Override
        public String toString() {
            return "Ok(" + value + ")";
        }
    }

    record Err(ValidationErr error) implements Result {
        @Override
        public String toString() {
            return "Err(" + error + ")";
        }
    }
}
